import java.util.*;

class Solution {
  private static final long MOD = 1_000_000_007L;

  public int[] waysToFillArray(int[][] queries) {
    int max = 0;
    for (int[] q : queries) max = Math.max(max, q[0] + 14);
    long[] fact = new long[max + 1], invFact = new long[max + 1];
    fact[0] = 1;
    for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
    invFact[max] = modPow(fact[max], MOD - 2);
    for (int i = max; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int n = queries[qi][0], k = queries[qi][1];
      long ways = 1;
      for (int p = 2; p * p <= k; p++)
        if (k % p == 0) {
          int e = 0;
          while (k % p == 0) {
            k /= p;
            e++;
          }
          ways = ways * choose(n + e - 1, e, fact, invFact) % MOD;
        }
      if (k > 1) ways = ways * n % MOD;
      ans[qi] = (int) ways;
    }
    return ans;
  }

  private long choose(int n, int r, long[] fact, long[] invFact) {
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
  }

  private long modPow(long a, long e) {
    long result = 1;
    while (e > 0) {
      if ((e & 1) != 0) result = result * a % MOD;
      a = a * a % MOD;
      e >>= 1;
    }
    return result;
  }
}
